// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: fund Alice
        address alice = address(0x1234);
        address bob = address(0x5678);
        vm.deal(alice, 10 ether);

        // Alice deposits 1 ether
        vm.prank(alice);
        c.deposit{value: 1 ether}();

        // Bob deposits 0 ether (just a call)
        vm.prank(bob);
        c.deposit{value: 0 ether}();

        // Alice withdraws all
        vm.prank(alice);
        c.withdrawAll();

        // Reference: balance = 0 (1 in - 1 out). Bug: balance = 2 (1 in + 1 added in withdrawAll)
        assertTrue(address(c).balance == 0 ether, "balance should be 0");
    }
}
